#!/usr/bin/env python3
from pwn import *

def try_exploit():
    # Connect to the server
    p = remote("pwn.chal.csaw.io", 8000)

    try:
        # Wait for initial prompt
        p.recvuntil(b"Enter option:", timeout=2)

        # Try option 1
        p.sendline(b"1")
        p.recvuntil(b"Enter size:", timeout=2)
        p.sendline(b"8")
        p.recvuntil(b"Enter bytes:", timeout=2)

        # Send bytes with proper encoding
        payload = bytes.fromhex('deadbeefcafebabe')
        p.send(payload)

        # Try to receive more data
        while True:
            try:
                response = p.recv(timeout=1)
                if response:
                    log.info(f"Received: {response}")
                else:
                    break
            except EOFError:
                break

    except Exception as e:
        log.error(f"Error: {str(e)}")
    finally:
        p.close()

def main():
    context.log_level = 'debug'
    try_exploit()

if __name__ == "__main__":
    main()

